import { test, expect } from '@playwright/test';

test.describe('Sticky Footer Navigation on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 820 });
    await page.goto('/home');
  });

  test('should display sticky footer navigation when content is short', async ({ page }) => {
    // Verify main content is visible
    const content = page.getByRole('main');
    await expect(content).toBeVisible();

    // Verify footer navigation is visible and sticky
    const footerNav = page.getByRole('navigation', { name: /footer/i });
    await expect(footerNav).toBeVisible();

    // Verify navigation items are visible
    const homeBtn = page.getByRole('button', { name: /home/i });
    const searchBtn = page.getByRole('button', { name: /search/i });
    const profileBtn = page.getByRole('button', { name: /profile/i });
    await expect(homeBtn).toBeVisible();
    await expect(searchBtn).toBeVisible();
    await expect(profileBtn).toBeVisible();

    // Verify footer is fixed at the bottom of the viewport
    const footerBoundingBox = await footerNav.boundingBox();
    expect(footerBoundingBox.y).toBeGreaterThan(page.viewportSize().height - 100);
    expect(footerBoundingBox.height).toBeGreaterThan(50);

    // Verify navigation buttons are accessible
    await expect(homeBtn).toBeEnabled();
    await expect(searchBtn).toBeEnabled();
    await expect(profileBtn).toBeEnabled();
  });

  test('should scroll content and keep footer sticky when content is long', async ({ page }) => {
    // Verify initial footer position
    const footerNav = page.getByRole('navigation', { name: /footer/i });
    const footerBoundingBox = await footerNav.boundingBox();
    expect(footerBoundingBox.y).toBeGreaterThan(page.viewportSize().height - 100);

    // Scroll down to trigger sticky behavior
    const scrollButton = page.getByRole('button', { name: /scroll to top/i });
    await scrollButton.click();

    // Verify footer remains visible and sticky after scrolling
    const footerBoundingBoxAfterScroll = await footerNav.boundingBox();
    expect(footerBoundingBoxAfterScroll.y).toBeGreaterThan(page.viewportSize().height - 100);

    // Verify navigation buttons are still visible and accessible
    const homeBtn = page.getByRole('button', { name: /home/i });
    const searchBtn = page.getByRole('button', { name: /search/i });
    const profileBtn = page.getByRole('button', { name: /profile/i });
    await expect(homeBtn).toBeVisible();
    await expect(searchBtn).toBeVisible();
    await expect(profileBtn).toBeVisible();

    // Verify footer height is consistent
    const footerHeight = await footerNav.evaluate((el) => el.offsetHeight);
    expect(footerHeight).toBeGreaterThan(50);
  });
});
